package hotel.messages;

import hotel.EmptyDatabase;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TestModeEmailSenderTest {

    private EmptyDatabase database;
    private SentMessages sentMessages;
    private TestableEmailSender emailSender;

    @BeforeEach
    void setup() {
        database = new EmptyDatabase();
        sentMessages = new SentMessages(database.dataSource());
        emailSender = new TestableEmailSender(sentMessages);
    }

    @AfterEach
    void cleanup() {
        database.close();
    }

    @Test
    void testModeRedirectsToTestEmail() {
        emailSender.setTestMode(true);
        emailSender.send("guest@example.com", "Subject", "Body");

        List<Message> messages = sentMessages.all();
        assertEquals(1, messages.size());
        assertEquals("SENT", messages.get(0).status());
        assertEquals("testes@pousadamarealta.com.br", messages.get(0).to());
        assertTrue(messages.get(0).subject().startsWith("[TESTE] "));
        assertTrue(messages.get(0).body().contains("Destinatário original: guest@example.com"));
    }

    @Test
    void testModeDoesNotCreateArchiveCopy() {
        emailSender.setTestMode(true);
        emailSender.send("guest@example.com", "Subject", "Body");

        List<Message> messages = sentMessages.all();
        assertEquals(1, messages.size());
        assertEquals("testes@pousadamarealta.com.br", messages.get(0).to());
    }

    @Test
    void normalModeCreatesArchiveCopy() {
        emailSender.setTestMode(false);
        emailSender.send("guest@example.com", "Subject", "Body");

        List<Message> messages = sentMessages.all();
        assertEquals(2, messages.size());
        assertEquals("guest@example.com", messages.get(0).to());
        assertEquals("arquivo@pousadamarealta.com.br", messages.get(1).to());
    }

    private static class TestableEmailSender extends EmailSender {
        private boolean testMode = false;

        TestableEmailSender(SentMessages sentMessages) {
            super(sentMessages);
        }

        void setTestMode(boolean testMode) {
            this.testMode = testMode;
        }

        @Override
        public Message send(String to, String subject, String body) {
            EmailToSend email = new EmailToSend(to, subject, body);
            String originalTo = to;
            for (EmailRule rule : getRules()) {
                ProcessingResult result = rule.process(email);
                if (result.isBlocked()) {
                    return getSentMessages().add("EMAIL", originalTo, subject, body, "BLOCKED");
                }
                email = result.email();
            }
            Message sent = getSentMessages().add("EMAIL", email.to(), email.subject(), email.body(), "SENT");
            if (!testMode) {
                getSentMessages().add("EMAIL", "arquivo@pousadamarealta.com.br", "[Cópia] " + email.subject(),
                        email.body(), "SENT");
            }
            return sent;
        }

        protected java.util.List<EmailRule> getRules() {
            try {
                var field = EmailSender.class.getDeclaredField("rules");
                field.setAccessible(true);
                return (java.util.List<EmailRule>) field.get(this);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        protected SentMessages getSentMessages() {
            try {
                var field = EmailSender.class.getDeclaredField("sentMessages");
                field.setAccessible(true);
                return (SentMessages) field.get(this);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }
}

